package me.raddatz.veyq.core.crypto

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.nio.ByteBuffer
import java.util.Base64
import java.util.HexFormat

/**
 * The backend's `grant` statement is the contract's (`grant_signature` in the crypto vectors, generated by an
 * independent Python implementation and asserted by `packages/crypto` too). The server rebuilds it to verify a staged
 * self-grant of an account rotation under the identity its stage declares (cr-secure-the-account decision 3); a drift
 * between the two stacks is every rotation's stage refused `422 self_grant_invalid` — this reddens first.
 */
class GrantSignatureTest {

    private val v: JsonNode = ObjectMapper().readTree(File("../../contracts/crypto/vectors/v1.json"))["grant_signature"]

    /** The vector's signer as an identity bundle `lp(kem) || lp(sign)` — the shape the server verifies under. */
    private val signer = b64(lp(ByteArray(1216) { 7 }) + lp(hex(v["sign_public"])))

    @Test
    fun bothCasesAreTheVectorsAndTheirSignaturesVerify() {
        for (name in listOf("personal", "group")) {
            val c = v[name]
            val stmt = statement(c)
            assertArrayEquals(hex(c["statement"]), stmt, name)
            assertTrue(GrantSignature.verify(signer, stmt, b64(hex(c["signature"]))), name)
        }
    }

    @Test
    fun aSignatureAnswersForNoOtherScopeKindEpochRecipientOrCiphertext() {
        val c = v["personal"]
        val ctx = c["context"]
        val sig = b64(hex(c["signature"]))
        val key = b64(hex(c["recipient_identity_public_key"]))
        val grant = b64(hex(c["wrapped_grant"]))
        val other = "c0ffee00-0000-4000-8000-0000000000e0"
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(other, "PERSONAL", 0, ctx["recipientUserId"].asText(), key, grant), sig))
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(ctx["scopeId"].asText(), "GROUP", 0, ctx["recipientUserId"].asText(), key, grant), sig))
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", 1, ctx["recipientUserId"].asText(), key, grant), sig))
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", 0, other, key, grant), sig))
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", 0, ctx["recipientUserId"].asText(), signer, grant), sig))
        assertFalse(GrantSignature.verify(signer, GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", 0, ctx["recipientUserId"].asText(), key, "AQ=="), sig))
        assertTrue(GrantSignature.verify(signer, statement(c), sig), "control: the vector's own context")
    }

    @Test
    fun everyMalformedInputIsARefusalNeverAnException() {
        val c = v["personal"]
        val ctx = c["context"]
        val key = b64(hex(c["recipient_identity_public_key"]))
        assertNull(GrantSignature.statement("C0FFEE00-0000-4000-8000-000000000004", "PERSONAL", 0, ctx["recipientUserId"].asText(), key, "AQ=="), "a non-canonical id")
        assertNull(GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", -1, ctx["recipientUserId"].asText(), key, "AQ=="), "a negative epoch")
        assertNull(GrantSignature.statement(ctx["scopeId"].asText(), "PERSONAL", 0, ctx["recipientUserId"].asText(), "not base64 !", "AQ=="), "a key that is no base64")
        val stmt = statement(c)
        assertFalse(GrantSignature.verify(null, stmt, b64(hex(c["signature"]))))
        assertFalse(GrantSignature.verify(key, stmt, b64(hex(c["signature"]))), "a bundle without an Ed25519 half")
        assertFalse(GrantSignature.verify(signer, stmt, "not base64 !"))
        assertFalse(GrantSignature.verify(signer, null, b64(hex(c["signature"]))))
    }

    private fun statement(c: JsonNode): ByteArray? {
        val ctx = c["context"]
        return GrantSignature.statement(
            ctx["scopeId"].asText(), ctx["scopeKind"].asText(), ctx["epoch"].asLong(), ctx["recipientUserId"].asText(),
            b64(hex(c["recipient_identity_public_key"])), b64(hex(c["wrapped_grant"])),
        )
    }

    private fun lp(b: ByteArray) = ByteBuffer.allocate(4).putInt(b.size).array() + b
    private fun hex(n: JsonNode): ByteArray = HexFormat.of().parseHex(n.asText())
    private fun b64(b: ByteArray): String = Base64.getEncoder().encodeToString(b)
}
